import { existsSync, readFileSync, realpathSync } from 'node:fs';
import { basename, join, resolve } from 'node:path';
import { majorOf, satisfies } from './semver.js';
export const SKIP_PLUGINS = 'mint-skip';
export const REACT_SPECIFIER = /^(react|react-dom)(\/.*)?$/;
export function isSkipped(pluginData) {
    return (typeof pluginData === 'object' &&
        pluginData !== null &&
        pluginData[SKIP_PLUGINS] === true);
}
export const skipData = { [SKIP_PLUGINS]: true };
function readJson(path) {
    try {
        return JSON.parse(readFileSync(path, 'utf8'));
    }
    catch {
        return undefined;
    }
}
export function readReactInfo(installRoot) {
    const diagnostics = [];
    const dirs = {};
    const versions = {};
    for (const name of ['react', 'react-dom']) {
        const dir = join(installRoot, 'node_modules', name);
        const pkg = existsSync(dir) ? readJson(join(dir, 'package.json')) : undefined;
        if (!pkg || typeof pkg.version !== 'string') {
            diagnostics.push({
                level: 'error',
                code: 'react-missing',
                message: `${name} is not installed. Add react and react-dom (18.x or 19.x) to package.json dependencies.`,
                pkg: name,
            });
            continue;
        }
        dirs[name] = realpathSync(dir);
        versions[name] = pkg.version;
    }
    const version = versions['react'];
    const domVersion = versions['react-dom'];
    const reactDir = dirs['react'];
    const reactDomDir = dirs['react-dom'];
    if (!version || !domVersion || !reactDir || !reactDomDir)
        return { diagnostics };
    return { info: { version, domVersion, reactDir, reactDomDir }, diagnostics };
}
export function checkReactVersions(version, domVersion) {
    const out = [];
    const major = majorOf(version);
    const domMajor = majorOf(domVersion);
    for (const [name, v, m] of [
        ['react', version, major],
        ['react-dom', domVersion, domMajor],
    ]) {
        if (m === undefined || m < 18) {
            out.push({
                level: 'error',
                code: 'react-unsupported-version',
                message: `${name} ${v} is not supported. Islands need React 18.x or 19.x.`,
                pkg: name,
            });
        }
    }
    if (out.length > 0 || version === domVersion)
        return out;
    if (major !== domMajor || (major !== undefined && major >= 19)) {
        out.push({
            level: 'error',
            code: 'react-version-mismatch',
            message: `react ${version} and react-dom ${domVersion} must be the exact same version (React ${major}.x throws "Incompatible React versions" at render). Pin both to the same version.`,
            pkg: 'react-dom',
        });
    }
    else {
        out.push({
            level: 'warning',
            code: 'react-version-mismatch',
            message: `react ${version} and react-dom ${domVersion} differ. React 18 tolerates this, but pin both to the same version.`,
            pkg: 'react-dom',
        });
    }
    return out;
}
export function packageOfPath(path) {
    const normalized = path.replace(/\\/g, '/');
    const withSlash = normalized.startsWith('/') ? normalized : `/${normalized}`;
    const idx = withSlash.lastIndexOf('/node_modules/');
    if (idx === -1)
        return undefined;
    const rest = withSlash.slice(idx + '/node_modules/'.length);
    const parts = rest.split('/');
    const name = rest.startsWith('@') ? parts.slice(0, 2).join('/') : parts[0];
    if (!name)
        return undefined;
    const dir = withSlash.slice(0, idx + '/node_modules/'.length) + name;
    return { name, dir: normalized.startsWith('/') ? dir : dir.slice(1) };
}
export function singleReactPlugin(opts) {
    return {
        name: 'mint-single-react',
        setup(build) {
            build.onResolve({ filter: REACT_SPECIFIER }, async (args) => {
                if (isSkipped(args.pluginData))
                    return undefined;
                const aliased = await build.resolve(args.path, {
                    kind: args.kind,
                    resolveDir: opts.installRoot,
                    pluginData: skipData,
                });
                if (aliased.errors.length > 0) {
                    return {
                        errors: [
                            {
                                text: `Could not resolve "${args.path}" from the docs project's node_modules. Add react and react-dom to package.json dependencies.`,
                            },
                        ],
                    };
                }
                if (/[\\/]node_modules[\\/]/.test(args.importer)) {
                    const natural = await build.resolve(args.path, {
                        kind: args.kind,
                        resolveDir: args.resolveDir,
                        pluginData: skipData,
                    });
                    const naturalPkg = natural.errors.length === 0 ? packageOfPath(natural.path) : undefined;
                    const aliasedPkg = packageOfPath(aliased.path);
                    const importerPkg = packageOfPath(args.importer);
                    if (naturalPkg && aliasedPkg && importerPkg && naturalPkg.dir !== aliasedPkg.dir) {
                        const nested = readJson(join(naturalPkg.dir, 'package.json'));
                        opts.onReplaced({
                            pkg: importerPkg.name,
                            dir: naturalPkg.dir,
                            version: typeof nested?.version === 'string' ? nested.version : undefined,
                        });
                    }
                }
                return { path: aliased.path, sideEffects: aliased.sideEffects };
            });
        },
    };
}
export const NAMESPACED = /^(?![A-Za-z]:[\\/])[^\\/]+:/;
function inputPackages(metafile, absWorkingDir) {
    const byDir = new Map();
    for (const input of Object.keys(metafile.inputs)) {
        if (NAMESPACED.test(input))
            continue;
        const pkg = packageOfPath(input);
        if (!pkg)
            continue;
        const dir = resolve(absWorkingDir, pkg.dir);
        const declared = readJson(join(dir, 'package.json'))?.name;
        const name = typeof declared === 'string' ? declared : pkg.name;
        const entry = byDir.get(dir) ?? { name, dir, files: [] };
        entry.files.push(resolve(absWorkingDir, input));
        byDir.set(dir, entry);
    }
    return [...byDir.values()];
}
const REACT_BUILD = /^(react|react-dom(?:-[a-z]+)*)\.(production|development|profiling)(\.min)?\.js$/;
function vendoredBuild(file, name) {
    const built = REACT_BUILD.exec(basename(file))?.[1];
    if (built === undefined)
        return false;
    return name === 'react' ? built === 'react' : built.startsWith('react-dom');
}
export function checkDuplicateReact(metafile, absWorkingDir, label) {
    const out = [];
    const pkgs = inputPackages(metafile, absWorkingDir);
    for (const name of ['react', 'react-dom']) {
        const reactDirs = pkgs.filter((p) => p.name === name).map((p) => p.dir);
        const vendored = pkgs
            .filter((p) => p.name !== 'react' && p.name !== 'react-dom')
            .filter((p) => p.files.some((file) => vendoredBuild(file, name)))
            .map((p) => `${p.dir} (bundled into ${p.name})`);
        const dirs = [...reactDirs, ...vendored];
        if (dirs.length > 1) {
            out.push({
                level: 'error',
                code: 'react-duplicate',
                message: `The ${label} bundle contains ${dirs.length} copies of ${name}: ${dirs.join(', ')}. Islands need exactly one React.`,
                pkg: name,
            });
        }
    }
    return out;
}
export function reactPackageDirs(metafile, absWorkingDir) {
    const pkgs = inputPackages(metafile, absWorkingDir);
    return {
        react: pkgs.filter((p) => p.name === 'react').map((p) => p.dir),
        'react-dom': pkgs.filter((p) => p.name === 'react-dom').map((p) => p.dir),
    };
}
const REACT_OWN_PACKAGES = new Set(['react', 'react-dom', 'scheduler', 'react-is']);
const REMOVED_APIS = [
    { pattern: /\bfindDOMNode\b/, api: 'findDOMNode' },
    {
        pattern: /\b(?:ReactDOM|ReactDom|_reactDom)\.(?:render|hydrate|unmountComponentAtNode)\s*\(/,
        api: 'ReactDOM.render',
    },
    { pattern: /\.defaultProps\s*=(?!=)/, api: '.defaultProps =' },
];
export function scanRemovedApis(metafile, absWorkingDir, reactVersion) {
    const major = majorOf(reactVersion);
    if (major === undefined || major < 19)
        return [];
    const out = [];
    for (const pkg of inputPackages(metafile, absWorkingDir)) {
        if (REACT_OWN_PACKAGES.has(pkg.name))
            continue;
        const found = new Set();
        for (const file of pkg.files) {
            let src;
            try {
                src = readFileSync(file, 'utf8');
            }
            catch {
                continue;
            }
            for (const { pattern, api } of REMOVED_APIS) {
                if (!found.has(api) && pattern.test(src))
                    found.add(api);
            }
            if (found.size === REMOVED_APIS.length)
                break;
        }
        if (found.size > 0) {
            out.push({
                level: 'warning',
                code: 'react-removed-api',
                message: `${pkg.name} uses APIs that React ${major} removed (${[...found].join(', ')}). It may crash or render wrong output; pin React 18 if it does.`,
                pkg: pkg.name,
            });
        }
    }
    return out;
}
export function checkPeerRanges(metafile, absWorkingDir, info) {
    const out = [];
    const installed = { react: info.version, 'react-dom': info.domVersion };
    for (const pkg of inputPackages(metafile, absWorkingDir)) {
        if (REACT_OWN_PACKAGES.has(pkg.name))
            continue;
        const json = readJson(join(pkg.dir, 'package.json'));
        const peers = json?.peerDependencies;
        if (typeof peers !== 'object' || peers === null)
            continue;
        for (const [peer, version] of Object.entries(installed)) {
            const range = peers[peer];
            if (typeof range !== 'string')
                continue;
            if (satisfies(version, range) === false) {
                out.push({
                    level: 'warning',
                    code: 'react-peer-range',
                    message: `${pkg.name}@${String(json?.version ?? '?')} declares peer ${peer}@"${range}", which excludes the installed ${peer} ${version}.`,
                    pkg: pkg.name,
                });
            }
        }
    }
    return out;
}
